insert into public.shruthi_project_knowledge(scope,topic,content,source_type,source_date,priority,tags)
values
('architecture','store_database_topology','Each managed storefront has its own store-scoped Supabase/data boundary while CentralHub is the master control plane. Cross-store operations must preserve store_id/store scope and must not silently mix customer, order, product-publication or integration state between stores.','curated_chat','2026-09-14',98,array['architecture','supabase','store-scope','multi-store']),
('architecture','sync_transport_contract','The four-store sync design supports store-to-CentralHub inbound order/product flows, targeted single-order refresh, and CentralHub-to-store operational status/payment/refund propagation. TamilRetail has used a signed gateway transport while the other stores have used direct service-role transport; verify current configuration before changing transport.','curated_chat','2026-09-14',92,array['sync','orders','tamilretail','transport']),
('admin','single_super_admin','CentralHub is intentionally operated with one super-admin user. Assistant and privileged internal features should be admin-gated and should not broaden access to ordinary authenticated users.','curated_chat','2026-09-14',100,array['admin','security','auth']),
('products','approval_rule','A product is not ready for storefront publication merely because a row exists. Admin approval should verify category, image, description and SEO/publication readiness; CentralHub remains the authoritative approval point.','curated_chat','2026-09-14',92,array['products','approval','seo','publication']),
('products','variant_identity','Product variants and cross-store matching should preserve product name, brand, category and normalized measurement/pack identity. Do not merge distinct pack sizes or product types just because names look similar.','curated_chat','2026-09-14',88,array['products','variants','brand','pack-size']),
('pricing','manual_engine','Pricing is manual-first: pricing_mode=manual, auto_apply=false, recent baseline/guardrails apply, major movements require review, and automatic price changes must not bypass approval.','curated_chat','2026-09-14',95,array['pricing','manual','approval','guardrails']),
('competitors','matching_pipeline','Competitor matching is high precision: require brand parity, normalized pack-size/measurement parity and product-type integrity before treating a competitor listing as authoritative. AI resolution is restricted, suspicious matches are cleaned, Dry Run is the default and final changes go through Approval Centre.','curated_chat','2026-09-14',92,array['competitors','matching','dry-run','approval']),
('analytics','store_scoped_metrics','Analytics should support per-store visits, traffic source attribution, realtime users, pages/product views and attribution to orders. CentralHub may aggregate these internally, but storefront/customer-facing tracking must not reveal CentralHub as the controller.','curated_chat','2026-09-14',90,array['analytics','traffic','ga','privacy']),
('marketing','integration_state','Marketing integrations are store-scoped. Campaign Manager and audiences may be functional even when a provider connection or OAuth setup is incomplete; Shruthi should distinguish configured, connected, syncing and placeholder/setup-required states instead of assuming a connection works.','curated_chat','2026-09-14',82,array['marketing','oauth','google','meta']),
('whatsapp','cloud_architecture','CentralHub WhatsApp uses store-scoped channels/contacts/messages and Cloud API webhooks/templates. OTP and order-event messaging must remain idempotent and store-scoped; receive-only webhook/event logging and template delivery state should be treated separately.','curated_chat','2026-09-14',90,array['whatsapp','cloud-api','otp','orders']),
('whatsapp','support_notification_rule','For customer-support notifications, avoid duplicate alerts: do not notify simply because AI already handled a message; notify when there is no response for the configured delay or when AI raises/escalates a ticket. Preserve store branding in notifications.','curated_chat','2026-09-14',88,array['whatsapp','support','notifications','tickets']),
('customer_care','inbox_contract','The support inbox should behave like a WhatsApp-style operational inbox, keep message history trustworthy, and preserve store/customer context. Do not fabricate deletions/edits or silently lose inbound media; unresolved delivery/media/AI response issues are operational incidents.','curated_chat','2026-09-14',80,array['support','inbox','whatsapp','customer-care']),
('finance','reconciliation_model','Finance reconciliation combines bank activity, documents/invoices and connected mail signals. AI may suggest accounting heads/classifications and reconciliation matches, but uncertain matches should remain reviewable. Reconciliation status must reflect actual applied state, not merely a suggestion.','curated_chat','2026-09-14',90,array['finance','bank','reconciliation','gmail']),
('finance','accrual_prepaid_rule','Multi-period costs such as long-term hosting should be represented through accrual/prepaid allocation over the applicable months rather than expensed entirely in one period when the accounting workflow calls for allocation.','curated_chat','2026-09-14',82,array['finance','accrual','prepaid','accounting']),
('purchase','backorder_planning','Backorder/procurement planning uses demand, lead time, safety stock and forward coverage to identify stockout risk and draft purchase needs. PO creation, receiving and reconciliation should remain auditable and store/supplier aware.','curated_chat','2026-09-14',88,array['purchase','backorder','stock','po']),
('automation','control_centre','Automation Control Centre uses explicit module toggles, risk levels, idempotency, fresh-data gates and a global kill switch. Dry Run is the safe default for consequential automation; low-risk reversible actions may be automated while sensitive actions require approval.','curated_chat','2026-09-14',95,array['automation','dry-run','risk','kill-switch']),
('monitoring','reliability_model','CentralHub monitoring should cover security, site health, sync reliability, integrations and deployment/runtime errors. The dashboard should surface meaningful live state and avoid pretending that a stale cached card is realtime.','curated_chat','2026-09-14',88,array['monitoring','security','health','realtime']),
('dashboard','realtime_ui','Dashboard and operational analytics are expected to update live without manual refresh where supported, with dense useful first-view information and minimal wasted space. Security/health indicators should be clearly visible rather than decorative.','curated_chat','2026-09-14',78,array['dashboard','realtime','ui','security']),
('device','fold_ui_contract','CentralHub Android UI must work on Samsung Z Fold form factors: cover screen uses a mobile layout, unfolded screen should use the wider/desktop layout, all panels must remain scrollable, and sidebars/overlays must not trap or hide content. Back navigation should go to the previous app/page state rather than unexpectedly exiting.','curated_chat','2026-09-14',85,array['android','zfold','responsive','navigation']),
('android','update_distribution','Native Android changes are distributed as signed APK updates through the CentralHub update feed. New native behavior must be compiled and signing identity verified before describing an APK as installable. Web-only changes should not unnecessarily force a native APK update.','curated_chat','2026-09-14',88,array['android','apk','updates','signing']),
('orders','fulfilment_shipping','Order operations include picking, packing, ready-to-ship, collected/in-transit/shipped and delivered states. DHL eCommerce UK is part of the established fulfilment context for MalluSpices; operational status mapping and tracking must stay consistent across CentralHub and storefronts.','curated_chat','2026-09-14',82,array['orders','fulfilment','dhl','tracking']),
('reviews','trustpilot_rule','When the internal customer rating is at least 4.0 and the review workflow is active, the review-link rule may send the Trustpilot request. Do not send it when the gating condition is not met.','curated_chat','2026-09-14',72,array['reviews','trustpilot','customer']),
('assistant','conversation_continuity','Shruthi should preserve conversational continuity across short follow-ups, avoid replaying stale answers after End/close, support interruption/barge-in, and prefer immediate acknowledgement plus concise spoken answers. A completed/ended conversation must not be resurrected by a late network or TTS result.','curated_chat','2026-09-14',98,array['shruthi','conversation','voice','barge-in']),
('assistant','external_task_handoff','When a request genuinely requires an external public website or account UI, Shruthi should delegate to the visible Live Web browser rather than claiming the internal read-only endpoint cannot help. She should narrate progress briefly, ask for ordinary missing facts, hand over for authentication secrets, and request approval at the final consequential boundary.','curated_chat','2026-09-14',100,array['shruthi','live-web','handoff','computer-use'])
